using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "VendettaEffect", menuName = "Data/Battle/Effects/Vendetta Effect")]
public class VendettaEffect : Effect
{
	[SerializeField]
	private DefaultEffectAction empowerAction;

	[SerializeField]
	private Effect tormentEffect;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		return GetVendettaDescription(-1, EffectsValues.NO_VALUE);
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return GetVendettaDescription(amount, amount);
	}

	private string GetVendettaDescription(int empowerAmount, int tormentAmount)
	{
		return GetDefaultVendettaDescription(empowerAmount) + "\n" + GetTormentDescription(tormentAmount);
	}

	private string GetDefaultVendettaDescription(int amount)
	{
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedEffectOwnerReceiveEffectFormatted(empowerAction.Effect, amount));
	}

	private string GetTormentDescription(int amount)
	{
		return tormentEffect.GetEffectDescription(amount);
	}

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		ApplyEmpower(effectOwner, amount);
		return amount;
	}

	private void ApplyEmpower(GameObject effectOwner, int amount)
	{
		empowerAction.CastTargetAmount(effectOwner, amount, null);
	}
}
